export const publicCopy = new Map(
  copy.map(([pt, en, fr]) => [normalizeCopy(pt), { pt, en, fr }]),
);

export function normalizeCopy(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

export function translatePublicCopy(value: string, language: Language) {
  const translated = publicCopy.get(normalizeCopy(value));
  if (translated) return translated[language];

  const titleSuffix = " — FIVAA";
  if (value.endsWith(titleSuffix)) {
    const prefix = value.slice(0, -titleSuffix.length);
    const translatedPrefix = publicCopy.get(normalizeCopy(prefix))?.[language];
    if (translatedPrefix) return `${translatedPrefix}${titleSuffix}`;
  }

  return value;
}
